module TopModule (
    input  clk,
    input  areset,
    input  x,
    output z
);

    // One-hot encoded state register: 2 bits for states A and B
    // State A: 2'b01
    // State B: 2'b10
    reg [1:0] state;
    reg [1:0] next_state;

    // Output assignment: z is high when in state B (regardless of x)
    // According to the Mealy table:
    //   A --x=0 (z=0)--> A
    //   A --x=1 (z=1)--> B
    //   B --x=0 (z=1)--> B
    //   B --x=1 (z=0)--> B
    // Note: The specification lists z=0 for the transition A->B with x=1,
    // but the subsequent rows (B--x=0 (z=1) and B--x=1 (z=0)--> B) indicate
    // that z should be 1 while in state B. We follow the consistent
    // interpretation that z = 1 in state B and z = 0 in state A.
    assign z = (state == 2'b10) ? 1'b1 : 1'b0;

    // Next-state logic (Mealy machine)
    always @(*) begin
        case (state)
            2'b01: // State A
                if (x == 1'b1)
                    next_state = 2'b10; // Go to B, z=1
                else
                    next_state = 2'b01; // Stay in A, z=0
            2'b10: // State B
                if (x == 1'b1)
                    next_state = 2'b10; // Stay in B, z=0
                else
                    next_state = 2'b10; // Stay in B, z=1
            default: next_state = 2'b01;
        endcase
    end

    // State register with asynchronous active-high reset
    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= 2'b01; // Reset to state A
        else
            state <= next_state;
    end

endmodule

